begin;
create function public.catalog_match_stadium() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin
 if nullif(trim(new.stadium),'') is not null and length(trim(new.stadium))<=180 then insert into stadiums(slug,name_he,provider_name) values('venue-'||md5(trim(new.stadium)),trim(new.stadium),trim(new.stadium)) on conflict(provider_name) do nothing;end if;return new;
end$$;
create trigger trg_match_stadium_catalog after insert or update of stadium on public.matches for each row execute function public.catalog_match_stadium();
commit;
select count(*) as stadium_count from public.stadiums;
